#if NOTE_API_VERSION >= NOTE_VERSION(7, 2, 1) || !defined(NOTE_API_STRICT)
                    if (note::flash(keys_::rsp_off) == k_) { rsp.off = v_; return; }
#endif
                    if (note::flash(keys_::rsp_set) == k_) { rsp.set = v_; return; }
